import re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']

def find_blocks(g):
    h,w=len(g),len(g[0]); blocks={}
    seen=set()
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v and (r,c) not in seen:
                # BFS
                stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen or not(0<=y<h and 0<=x<w) or g[y][x]!=v: continue
                    seen.add((y,x)); comp.append((y,x))
                    stack+= [(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                if len(comp)>=4:
                    ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                    blocks[v]=(min(ys),max(ys),min(xs),max(xs),len(comp))
    return blocks
print(find_blocks(inp))

def transform(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    H={}; V={}
    for v,(r0,r1,c0,c1,n) in find_blocks(g).items():
        H[(r0+r1)//2]=v; V[(c0+c1)//2]=v
    res=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if r in H and c in V: res[r][c]=0
            elif r in H: res[r][c]=H[r]
            elif c in V: res[r][c]=V[c]
    return res
